<script setup lang="ts">
import { ChevronLeft, ChevronRight } from './internal/icons';
import { computed, ref, watch, nextTick, getCurrentInstance } from 'vue';
import './styles/theme.css'; import './styles/calendar.css';
type Mode = 'month' | 'year';
const props = withDefaults(defineProps<{ modelValue?: Date; defaultValue?: Date; mode?: Mode; defaultMode?: Mode; fullscreen?: boolean; disabledDate?: (date: Date) => boolean; validRange?: [Date, Date]; firstDayOfWeek?: 0 | 1; weekdayLabels?: string[]; showToday?: boolean }>(), { defaultMode: 'month', fullscreen: true, firstDayOfWeek: 1, weekdayLabels: () => ['日', '一', '二', '三', '四', '五', '六'], showToday: true });
const emit = defineEmits<{ 'update:modelValue': [value: Date]; change: [value: Date]; 'update:mode': [mode: Mode]; panelChange: [date: Date, mode: Mode]; select: [date: Date, info: { source: 'date' | 'month' | 'today' | 'keyboard' }] }>();
const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate()); const today = startOfDay(new Date()); const inner = ref(props.defaultValue ?? today), innerMode = ref(props.defaultMode); const selected = computed(() => props.modelValue ?? inner.value), mode = computed(() => props.mode ?? innerMode.value); const viewing = ref(new Date(selected.value.getFullYear(), selected.value.getMonth(), 1)), focused = ref(selected.value), grid = ref<HTMLElement | null>(null); const id = `at-calendar-${getCurrentInstance()?.uid}`;
const sameDay = (left: Date, right: Date) => left.getFullYear() === right.getFullYear() && left.getMonth() === right.getMonth() && left.getDate() === right.getDate(); const sameMonth = (left: Date, right: Date) => left.getFullYear() === right.getFullYear() && left.getMonth() === right.getMonth(); const addDays = (date: Date, days: number) => new Date(date.getFullYear(), date.getMonth(), date.getDate() + days); const addMonths = (date: Date, months: number) => new Date(date.getFullYear(), date.getMonth() + months, Math.min(date.getDate(), new Date(date.getFullYear(), date.getMonth() + months + 1, 0).getDate()));
watch(selected, date => { viewing.value = new Date(date.getFullYear(), date.getMonth(), 1); focused.value = date; });
function disabled(date: Date) { return !!props.disabledDate?.(date) || !!(props.validRange && (startOfDay(date) < startOfDay(props.validRange[0]) || startOfDay(date) > startOfDay(props.validRange[1]))); }
function panel(date: Date, nextMode = mode.value) { viewing.value = new Date(date.getFullYear(), date.getMonth(), 1); if (props.mode === undefined) innerMode.value = nextMode; emit('update:mode', nextMode); emit('panelChange', date, nextMode); }
function select(date: Date, source: 'date' | 'month' | 'today' | 'keyboard') { if (disabled(date)) return; if (props.modelValue === undefined) inner.value = date; focused.value = date; emit('update:modelValue', date); emit('change', date); emit('select', date, { source }); if (!sameMonth(date, viewing.value)) panel(date); }
const weeks = computed(() => { const first = new Date(viewing.value.getFullYear(), viewing.value.getMonth(), 1); const start = addDays(first, -((first.getDay() - props.firstDayOfWeek + 7) % 7)); return Array.from({ length: 6 }, (_, week) => Array.from({ length: 7 }, (_, day) => addDays(start, week * 7 + day))); });
const months = computed(() => Array.from({ length: 12 }, (_, index) => new Date(viewing.value.getFullYear(), index, 1)));
function info(date: Date, type: 'date' | 'month') { return { type, today: type === 'date' ? sameDay(date, today) : sameMonth(date, today), selected: type === 'date' ? sameDay(date, selected.value) : sameMonth(date, selected.value), outside: type === 'date' && !sameMonth(date, viewing.value), disabled: disabled(date) }; }
async function key(event: KeyboardEvent) { let date: Date | undefined; const current = focused.value; if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); if (mode.value === 'year') { panel(current, 'month'); emit('select', current, { source: 'month' }); } else select(current, 'keyboard'); return; } if (['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(event.key)) { const delta = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: mode.value === 'month' ? -7 : -3, ArrowDown: mode.value === 'month' ? 7 : 3 }[event.key] ?? 0; date = mode.value === 'month' ? addDays(current, delta) : addMonths(current, delta); } if (event.key === 'PageUp' || event.key === 'PageDown') date = addMonths(current, (event.key === 'PageUp' ? -1 : 1) * (mode.value === 'year' || event.shiftKey ? 12 : 1)); if (mode.value === 'month' && (event.key === 'Home' || event.key === 'End')) date = addDays(current, -((current.getDay() - props.firstDayOfWeek + 7) % 7) + (event.key === 'End' ? 6 : 0)); if (!date) return; event.preventDefault(); focused.value = date; if (!sameMonth(date, viewing.value)) panel(date); await nextTick(); grid.value?.querySelector<HTMLElement>('[tabindex="0"]')?.focus(); }
</script>
<template><div :class="['at-calendar', fullscreen ? 'at-calendar--fullscreen' : 'at-calendar--card', `at-calendar--${mode}`]"><slot name="header" :value="viewing" :mode="mode" :on-change="panel" :on-mode-change="(next: Mode) => panel(viewing, next)"><header class="at-calendar__header"><div class="at-calendar__nav"><button type="button" class="at-calendar__nav-button" aria-label="上一年" @click="panel(addMonths(viewing, -12))"><ChevronLeft :size="16" /><ChevronLeft :size="16" class="at-calendar__nav-double" /></button><button v-if="mode === 'month'" type="button" class="at-calendar__nav-button" aria-label="上个月" @click="panel(addMonths(viewing, -1))"><ChevronLeft :size="16" /></button><strong :id="`${id}-label`" class="at-calendar__label" aria-live="polite">{{ viewing.getFullYear() }} 年{{ mode === 'month' ? ` ${viewing.getMonth() + 1} 月` : '' }}</strong><button v-if="mode === 'month'" type="button" class="at-calendar__nav-button" aria-label="下个月" @click="panel(addMonths(viewing, 1))"><ChevronRight :size="16" /></button><button type="button" class="at-calendar__nav-button" aria-label="下一年" @click="panel(addMonths(viewing, 12))"><ChevronRight :size="16" /><ChevronRight :size="16" class="at-calendar__nav-double" /></button></div><div class="at-calendar__actions"><button v-if="showToday" type="button" class="at-calendar__today" @click="select(today, 'today'); panel(today, 'month')">今天</button><div class="at-calendar__mode" role="radiogroup" aria-label="视图"><button v-for="item in (['month', 'year'] as const)" :key="item" type="button" role="radio" :aria-checked="mode === item" :class="['at-calendar__mode-option', { 'at-calendar__mode-option--active': mode === item }]" @click="panel(viewing, item)">{{ item === 'month' ? '月' : '年' }}</button></div></div></header></slot><div v-if="mode === 'month'" ref="grid" class="at-calendar__grid" role="grid" :aria-labelledby="`${id}-label`" @keydown="key"><div class="at-calendar__weekdays" role="row"><span v-for="index in 7" :key="index" class="at-calendar__weekday" role="columnheader">{{ weekdayLabels[(index - 1 + firstDayOfWeek) % 7] }}</span></div><div v-for="(week, index) in weeks" :key="index" class="at-calendar__week" role="row"><div v-for="date in week" :key="date.getTime()" role="gridcell" :tabindex="sameDay(date, focused) ? 0 : -1" :aria-selected="sameDay(date, selected)" :aria-disabled="disabled(date)" :aria-current="sameDay(date, today) ? 'date' : undefined" :aria-label="`${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日`" :class="['at-calendar__cell', { 'at-calendar__cell--selected': sameDay(date, selected), 'at-calendar__cell--today': sameDay(date, today), 'at-calendar__cell--outside': !sameMonth(date, viewing), 'at-calendar__cell--disabled': disabled(date) }]" @click="select(date, 'date')" @focus="focused = date"><span class="at-calendar__date">{{ date.getDate() }}</span><div v-if="fullscreen && $slots.cell" class="at-calendar__content"><slot name="cell" :date="date" :info="info(date, 'date')" /></div><span v-else-if="$slots.cell" class="at-calendar__dot-hint" aria-hidden="true" /></div></div></div><div v-else ref="grid" class="at-calendar__months" role="grid" @keydown="key"><div v-for="date in months" :key="date.getMonth()" role="gridcell" :tabindex="sameMonth(date, focused) ? 0 : -1" :aria-selected="sameMonth(date, selected)" :aria-disabled="disabled(date)" :aria-label="`${date.getFullYear()}年${date.getMonth() + 1}月`" :class="['at-calendar__cell', 'at-calendar__cell--month', { 'at-calendar__cell--selected': sameMonth(date, selected), 'at-calendar__cell--today': sameMonth(date, today), 'at-calendar__cell--disabled': disabled(date) }]" @click="!disabled(date) && (panel(date, 'month'), emit('select', date, { source: 'month' }))" @focus="focused = date"><span class="at-calendar__date">{{ ['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'][date.getMonth()] }}</span><div v-if="fullscreen && $slots.cell" class="at-calendar__content"><slot name="cell" :date="date" :info="info(date, 'month')" /></div></div></div></div></template>
